mapper.select:
SELECT s.id, s.activity_id, s.sku_id, s.product_id, s.merchant_id, s.seckill_price, s.origin_price, s.total_stock, s.available_stock, s.locked_stock, s.sold_stock, s.version, s.per_user_limit, s.sort, s.preheated, s.preheat_time, s.deleted, s.created_at, s.updated_at FROM seckill_stock s INNER JOIN seckill_activity a ON a.id = s.activity_id AND a.deleted = 0 WHERE s.deleted = 0 AND a.status IN ('pending', 'running') AND a.end_time > NOW() AND s.sku_id IN
#{skuId}
ORDER BY s.sort ASC, s.id ASC
